using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using OpenSecurityPlatform.Foundation;
#pragma warning disable CA1305 // CSV numeric evidence uses invariant wire values below.
sealed class ModuleExportWorker(IModuleExportRepository jobs, IModuleTelemetryRepository modules, IObjectStorage objects, ILogger<ModuleExportWorker> log) : BackgroundService { static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); protected override async Task ExecuteAsync(CancellationToken ct) { while (!ct.IsCancellationRequested) { foreach (var x in await jobs.ExpireDueAsync(ct)) foreach (var id in new[] { x.OutputObjectId, x.ManifestObjectId, x.MetadataObjectId }) try { await objects.DeleteAsync(x.TenantId, id.ToString("D"), ct); } catch { } var j = await jobs.ClaimAsync(ct); if (j is null) { await Task.Delay(250, ct); continue; } try { var page = await modules.SearchAsync(j.TenantId, j.Query with { Cursor = null, PageSize = Math.Clamp(j.MaximumRecords, 1, 10000) }, ct); var values = page.Items.Take(j.MaximumRecords).ToArray(); var output = j.Format == "csv" ? Csv(values) : Encoding.UTF8.GetBytes(string.Join('\n', values.Select(x => JsonSerializer.Serialize(x, Json))) + '\n'); var hash = Convert.ToHexString(SHA256.HashData(output)).ToLowerInvariant(); var at = DateTimeOffset.UtcNow; var manifest = JsonSerializer.SerializeToUtf8Bytes(new { schemaVersion = "module-export-manifest.v1", exportId = j.Id, tenantBinding = j.TenantId, j.Format, recordCount = values.Length, query = j.Query, fields = j.Fields, sha256 = hash, moduleEventSchemaVersion = "module-event.v1", j.OutputObjectId, j.MetadataObjectId, completedAt = at }, Json); var meta = JsonSerializer.SerializeToUtf8Bytes(new { schemaVersion = "module-export-metadata.v1", exportId = j.Id, j.Query, j.Fields, j.CreatedAt, j.ExpiresAt, outputSha256 = hash }, Json); await Put(j, j.OutputObjectId, output, j.Format == "csv" ? "text/csv" : "application/x-ndjson", ct); await Put(j, j.ManifestObjectId, manifest, "application/json", ct); await Put(j, j.MetadataObjectId, meta, "application/json", ct); await jobs.CompleteAsync(j.Id, values.Length, output.Length, hash, at, ct); } catch (Exception e) when (e is not OperationCanceledException) { log.LogError(e, "Module export failed"); await jobs.FailAsync(j.Id, "EXPORT_FAILED", e.GetType().Name, ct); } } } async Task Put(ModuleExportJob j, Guid id, byte[] b, string media, CancellationToken ct) { await using var s = new MemoryStream(b); await objects.UploadAsync(j.TenantId, id.ToString("D"), s, media, Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant(), ct); } static byte[] Csv(IEnumerable<ModuleObservation> v) { static string C(string? x) { var s = x ?? ""; if (s.Length > 0 && "=+-@\t\r".Contains(s[0])) s = "'" + s; return '"' + s.Replace("\"", "\"\"") + '"'; } var b = new StringBuilder("eventId,endpointId,observedAt,path,basename,imageType,mode,driver,loadAddress,sha256,signer,process,collector,quality\n"); foreach (var x in v) b.AppendLine(string.Join(',', C(x.EventId.ToString()), C(x.EndpointId.ToString()), C(x.ObservedAt.ToString("O")), C(x.OriginalPath), C(x.Basename), C(x.ImageType), C(x.Mode.ToString()), C(x.Driver.ToString()), C(x.LoadAddress?.ToString()), C(x.Hash.Value), C(x.Signer.Subject), C(x.Process?.ProcessEntityId), C(x.CollectorSource), C(string.Join(';', x.DataQualityFlags)))); return Encoding.UTF8.GetBytes(b.ToString()); } }
